import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Installation","description":"","frontmatter":{"title":"Installation","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"de/setup/installation.md","filePath":"de/setup/installation.md"}`),a={name:`de/setup/installation.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>OEA besteht aus einer PostgreSQL-Datenbank, einem einmaligen Migrationsschritt und dem Backend. Die Betreiberdatei <code>compose.yaml</code> im Repository startet alle drei mit Docker Compose (oder Podman Compose). Wenn du ein eigenes PostgreSQL betreibst, folge <a href="#eigenes-postgresql">Eigenes PostgreSQL</a>.</p><h2 id="voraussetzungen" tabindex="-1">Voraussetzungen <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to “Voraussetzungen”">​</a></h2><ul><li>Docker mit Compose v2 oder Podman mit Compose</li><li>PostgreSQL 15 oder neuer, wenn du eine eigene Datenbank verwendest (das Compose-Setup verwendet PostgreSQL 18)</li><li>Eine Datei für den Key-Encryption-Key, lesbar für den Container-Benutzer</li></ul><h2 id="mit-docker-compose-installieren" tabindex="-1">Mit Docker Compose installieren <a class="header-anchor" href="#mit-docker-compose-installieren" aria-label="Permalink to “Mit Docker Compose installieren”">​</a></h2><ol><li><p>Kopiere <code>.env.example</code> nach <code>.env</code> und fülle <strong>jeden</strong> Wert aus. Verwende lange Zufallswerte (mindestens 16 Zeichen); bekannte Entwicklungswerte werden abgelehnt. Committe <code>.env</code> nie.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Zweck</th></tr></thead><tbody><tr><td><code>POSTGRES_PASSWORD</code></td><td>PostgreSQL-Superuser, nur vom Provisioning-Skript beim ersten Start verwendet</td></tr><tr><td><code>OEA_OWNER_PASSWORD</code>, <code>OEA_REPORTING_OWNER_PASSWORD</code></td><td>Owner-Rollen des Migrationsschritts</td></tr><tr><td><code>OEA_APP_PASSWORD</code></td><td>Laufzeitrolle des Backends</td></tr><tr><td><code>OEA_AUDIT_CLEANUP_PASSWORD</code>, <code>OEA_AUDITOR_PASSWORD</code>, <code>OEA_ANALYTICS_PASSWORD</code></td><td>Rollen für Audit-Aufbewahrung, Audit-Prüfung und Analytics</td></tr><tr><td><code>OEA_KEK_FILE</code></td><td>Pfad der Datei mit dem Key-Encryption-Key</td></tr><tr><td><code>OEA_HTTP_BIND</code>, <code>OEA_HTTP_PORT</code></td><td>optional: veröffentlichte Adresse, Standard <code>127.0.0.1:8080</code></td></tr></tbody></table></li><li><p>Erzeuge den Key-Encryption-Key. Er verschlüsselt gespeicherte Geheimnisse (zweite Faktoren, Client-Secrets von Identity-Providern). Bewahre ihn außerhalb der Datenbank-Backups auf:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/urandom</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/path/oea-kek.key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0444</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/path/oea-kek.key</span></span></code></pre></div></li><li><p>Starte OEA:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Beim ersten Start führt PostgreSQL das Provisioning-Skript aus und legt die Datenbankrollen an. Danach erzeugt der Migrationsschritt das Schema, und das Backend startet.</p></li><li><p>Prüfe, ob die Instanz läuft:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/v1/health</span></span></code></pre></div><p>Die Antwort enthält nur den Gesamtstatus <code>UP</code> oder <code>DOWN</code>.</p></li></ol><p>Weiter geht es mit dem <a href="./first-administrator">ersten Administrator</a>.</p><div class="warning custom-block"><p class="custom-block-title">Öffentlicher Zugriff</p><p>Mach die Instanz nicht aus dem Internet erreichbar, bevor die Setup-Phase beendet ist (siehe <a href="./first-administrator">Erster Administrator</a>). Stell einen Reverse Proxy mit TLS vor OEA und setze die öffentliche Adresse mit <code>OEA_WEB_PUBLIC_URL</code> (<code>https</code>), bevor du einen Identity-Provider anbindest.</p></div><h2 id="eigenes-postgresql" tabindex="-1">Eigenes PostgreSQL <a class="header-anchor" href="#eigenes-postgresql" aria-label="Permalink to “Eigenes PostgreSQL”">​</a></h2><p>Wenn du eine verwaltete Cloud-Datenbank oder einen bestehenden Cluster verwendest, führst du Provisioning und Migration selbst aus.</p><h3 id="provisioning-einmalig" tabindex="-1">Provisioning (einmalig) <a class="header-anchor" href="#provisioning-einmalig" aria-label="Permalink to “Provisioning (einmalig)”">​</a></h3><p>Das Skript <code>deploy/postgres/initdb/10-oea-roles.sh</code> legt die sechs Datenbankrollen an, setzt ihre Passwörter, beschränkt <code>CONNECT</code> auf die Datenbank auf die OEA-Rollen und legt die Schemas mit ihren Ownern an. Du brauchst eine leere Datenbank (Standardname <code>oea</code>), eine Rolle, die Rollen anlegen darf, und <code>psql</code> 15 oder neuer:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PGHOST</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db.example.org PGPORT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PGUSER</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">postgres PGPASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OEA_DB_NAME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">oea</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OEA_OWNER_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_REPORTING_OWNER_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_APP_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OEA_AUDIT_CLEANUP_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_AUDITOR_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_ANALYTICS_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deploy/postgres/initdb/10-oea-roles.sh</span></span></code></pre></div><ul><li>Das Skript liest Passwörter nur aus der Umgebung; sie erscheinen nie auf der Kommandozeile oder in der Ausgabe.</li><li>Fehlt ein Passwort, bricht das Skript ab und nennt die fehlenden Variablen.</li><li>Du kannst das Skript erneut ausführen: Es setzt Rollenattribute, Passwörter und Schema-Owner zurück, du kannst damit also auch Rollenpasswörter rotieren.</li><li>Behandle jedes Passwort als Deployment-Geheimnis: Bewahre es in einem Secret Store auf, nicht in deiner Shell-History.</li></ul><p>Die Rollen beschreibt <a href="./../administration/operations#datenbankrollen">Betrieb</a>.</p><h3 id="migration-vor-jedem-start-einer-neuen-version" tabindex="-1">Migration (vor jedem Start einer neuen Version) <a class="header-anchor" href="#migration-vor-jedem-start-einer-neuen-version" aria-label="Permalink to “Migration (vor jedem Start einer neuen Version)”">​</a></h3><p>Schemamigrationen laufen in einem einmaligen Schritt, bevor das Backend startet, nie im laufenden Backend:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.migration.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.migration.owner.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_OWNER_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.migration.reporting-owner.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_REPORTING_OWNER_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Du kannst die Einstellungen auch als Umgebungsvariablen übergeben (<code>OEA_MIGRATION_URL</code>, <code>OEA_MIGRATION_OWNER_PASSWORD</code>, <code>OEA_MIGRATION_REPORTINGOWNER_PASSWORD</code>); ohne <code>oea.migration.url</code> wird <code>spring.datasource.url</code> verwendet. Der Schritt endet bei Erfolg mit Code <code>0</code> und bei jedem Fehler mit <code>1</code>.</p><table tabindex="0"><thead><tr><th>Migrationsset</th><th>Läuft als</th><th>Schema-History-Tabelle</th></tr></thead><tbody><tr><td><code>db/migration</code></td><td><code>oea_owner</code></td><td><code>public.flyway_schema_history</code></td></tr><tr><td><code>db/migration-audit</code></td><td><code>oea_owner</code></td><td><code>audit.flyway_schema_history</code></td></tr><tr><td><code>db/migration-reporting</code></td><td><code>oea_reporting_owner</code></td><td><code>reporting.flyway_schema_history</code></td></tr></tbody></table><h3 id="backend-starten" tabindex="-1">Backend starten <a class="header-anchor" href="#backend-starten" aria-label="Permalink to “Backend starten”">​</a></h3><p>Das Backend verbindet sich mit der Laufzeitrolle <code>oea_app</code>:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPRING_DATASOURCE_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPRING_DATASOURCE_USERNAME=oea_app </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPRING_DATASOURCE_PASSWORD=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_APP_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_SECURITY_KEK_CURRENT=/run/secrets/oea_kek </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_WEB_PUBLIC_URL=https://oea.example.org </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">java </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span></span></code></pre></div><ul><li><code>OEA_WEB_PUBLIC_URL</code> (<code>oea.web.public-url</code>) ist die Adresse, unter der die Benutzer OEA erreichen. Du brauchst sie, sobald ein Identity-Provider aktiviert ist; sie muss <code>https</code> verwenden und darf keine Loopback-Adresse sein.</li><li>Ist der Migrationsschritt für die aktuelle Version nicht gelaufen, startet das Backend nicht und nennt den Migrationsschritt.</li><li>Das Backend startet nicht, wenn die Schlüsseldatei fehlt, nicht lesbar ist, nicht genau 256 Bit hat oder der Entwicklungsschlüssel des Repositorys ist.</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};